# -*- coding: utf-8 -*-
import re
path='src/lalka-2/work/chapter-01/scaffold.txt'
tr={185:'— Приходжу з повіреним власника.',186:'— А цей пан чого хоче?',187:'— Цей пан і є повіреним.',188:'— То як же мені сказати?...',189:'— Скажіть пані, — відповів уже роздратований управитель, — що ми прийшли поговорити про помешкання...',190:'— Ага!',191:'Вона зачинила двері й відійшла. Минуло дві чи три хвилини, перш ніж вона повернулася й, відімкнувши безліч замків, провела нас до порожньої вітальні.',192:'Дивний вигляд мала ця вітальня. Меблі вкриті темно-сірими чохлами, так само фортепіано, так само люстра, підвішена до стелі; навіть колони з фігурками, що стояли по кутках, були вдягнені в попелясті чохли.',193:'Загалом кімната справляла враження помешкання, господар якого кудись виїхав, залишивши тільки служницю, що дбала про лад у домі.',194:'За дверима було чути розмову жіночим і чоловічим голосами. Жіночий належав баронесі; чоловічий я добре знав, але не міг пригадати, кому саме.',195:'— Присягнулася б, — казала баронеса, — що він має з нею стосунки. Позавчора послав їй букет із посильним...',196:'— Гм!... Гм!... — озвався чоловічий голос.',197:'— Букет, який ця огидна кокетка, щоб обдурити мене, звеліла негайно викинути у вікно...',198:'— Але ж барон у селі... так далеко від Варшави... — відповів чоловік.',199:'— Та в нього тут є приятелі, — вигукнула баронеса. — І якби я вас не знала, то подумала б, що ви йому допомагаєте в цих неподобствах.',200:'— Але ж, пані!... — запротестував чоловічий голос. І тієї ж миті пролунало два поцілунки, мабуть, у руку.',201:'— Ну-ну, пане Марушевичу, без ніжностей!... Знаю я вас. Ви засипаєте жінку пестощами, поки вона вам не довіриться, а потім розтринькуєте її маєток і вимагаєте розлучення...',202:'«То це Марушевич, — подумав я. — Гарна парочка...»',203:'— Я зовсім не такий, — тихіше відповів за дверима чоловічий голос, і знову пролунали два поцілунки, напевно, в руку.',204:'Я глянув на екс-поміщика. Він звів очі до стелі, а плечі підняв майже до вух.'}
lines=open(path,encoding='utf-8').read().splitlines(); i=-1; out=[]
for ln in lines:
 if ln.startswith('**PL:**'): i+=1
 if ln=='**UA:**' and i in tr: ln='**UA:** '+tr[i]
 out.append(ln)
open(path,'w',encoding='utf-8').write('\n'.join(out))
print('filled',len(tr),'units')
